SELECT accounts.account_type, QUARTER(accounts.opened_date) AS opened_quarter, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(transactions.txn_type))) AS txn_type_values, COUNT(*) AS total_count FROM transactions INNER JOIN accounts ON accounts.id = transactions.account_id WHERE accounts.status = 'OPEN' GROUP BY accounts.account_type, QUARTER(accounts.opened_date) ORDER BY total_count DESC;
